        major, minor, patch, prerelease = parse_version(v)

        # For sorting: (major, minor, patch, prerelease_sort_key)
        # Prerelease with identifiers should sort before without
        # We'll use a tuple where:
        # - (0, prerelease_identifiers) for versions with prerelease
        # - (1,) for versions without prerelease
        # This way, prerelease versions sort first

